import {drawFarmTile,drawFarmDecor,drawFarmTown,drawFarmLife,warmFarmSprites} from './cossenne-farm.js?v=0.90.20';
import {drawCompanion} from './companion.js?v=0.90.37';
export const ORCHARD_PIXEL_ASSETS={cossenneHouse:'../cossenne/house.webp',cossenneMarket:'../cossenne/market.webp',cossenneConservatory:'../cossenne/conservatory.webp',cossenneApothecary:'../cossenne/apothecary.webp',cossenneFirewatch:'../cossenne/firewatch.webp',cossenneKeep:'../cossenne/keep.webp',biomeorchardground:'../wildfire/living-ground-v071.webp',biomeorchardashground:'../wildfire/ash-ground-v071.webp',biomeorchardpath:'../wildfire/dirt-path-v071.webp',biomeorchardgrass:'../wildfire/encounter-grass-v071.webp',biomeorchardwater:'../wildfire/shrine-water-v071.webp',orchardScenery:'../wildfire/forest-props-v071.webp',cossenneScenery:'../wildfire/city-props-v071.webp',orchardFlames:'../wildfire/flame-v071.webp'};
const cell=n=>({x:n%4*64,y:Math.floor(n/4)*64,w:64,h:64});
export function drawOrchardTile(c,m,x,y,{road,grass,walk},asset){if(!m.orchardKind)return false;if(m.farm)return drawFarmTile(c,m,x,y,road,asset);if(m.orchardKind==='town'){asset(c,road?'bloomPath':'biomeorchardground',x,y);return true;}const ash=['burning','ash'].includes(m.orchardKind),name=m.orchardKind==='shrine'&&!walk?'biomeorchardwater':road?(m.orchardKind==='shrine'?'biomecoastpath':'biomeorchardpath'):grass?'biomeorchardgrass':ash?'biomeorchardashground':'biomeorchardground';asset(c,name,x,y);if(grass&&ash){c.save();c.fillStyle=m.orchardKind==='burning'?'#703d2733':'#77716d44';c.fillRect(x*16,y*16,16,16);c.restore();}return true;}
export function orchardScenery(m,walkable){const out=[];for(let y=2;y<27;y+=4)for(let x=2;x<43;x+=4){const seed=Math.floor(x/4)*7+Math.floor(y/4)*11;if(m.orchardKind==='shrine'&&(!walkable(x,y+4)||!walkable(x+1,y+4)))continue;if(![0,1,2].every(dx=>[0,1,2,3].every(dy=>!walkable(x+dx,y+dy)))||m.props.some(p=>x<p.x+p.w&&x+2>p.x&&y<p.y+p.h&&y+3>p.y))continue;const n=m.orchardKind==='burning'?seed%3===0?2:1:m.orchardKind==='ash'?1:m.orchardKind==='renewal'?seed%3===0?3:1:m.orchardKind==='shrine'?6:0;out.push({x,y,n,seed});}return out;}
export function drawOrchardDecor(c,m,asset,walkable){if(!m.orchardKind)return;if(m.farm){drawFarmDecor(c,m,asset);return;}for(const {x,y,n}of (m.orchardKind==='town'?[]:orchardScenery(m,walkable))){if(m.orchardKind==='shrine')asset(c,'biomecoastpath',x,y,3,4);asset(c,'orchardScenery',x-.2+(x%3)*.08,y-.3,3.4,4.4,cell(n));}if(m.orchardKind==='town'){drawFarmTown(c,m,asset);for(const [x,y]of [[1,3],[14,3],[44,3],[1,25],[44,25]])asset(c,'orchardScenery',x,y,3,4,cell(0));for(const [n,x,y,w,h]of [[6,29,21,3,3],[7,33,12,2,2]])asset(c,'cossenneScenery',x,y,w,h,cell(n));}for(const s of m.spots)if(s.id?.startsWith('ow-')&&s.id.includes('-control-')||s.id?.startsWith('cs-sluice-'))asset(c,'orchardScenery',s.x-1,s.y-1.3,2.5,2.5,cell(5));}
export function drawOrchardLife(c,state,room,time,reduced,species,m,asset,walkable){if(m?.orchardKind==='burning'){const frame=reduced?0:Math.floor(time/170)%4;for(const {x,y,n,seed}of orchardScenery(m,walkable))if(n===2&&seed%2===0)asset(c,'orchardFlames',x-.4,y,4,4,{x:frame*128,y:0,w:128,h:128});}if(m?.farm){warmFarmSprites();drawFarmLife(c,time,reduced,species);return;}if(room!=='cossenne')return;if(state.cossenne?.valves?.includes('west')){asset(c,'biomeorchardwater',17.1,25.6,.25,2.8);asset(c,'biomeorchardwater',17.1,28.4,13,.25);}if(state.cossenne?.valves?.includes('east')){asset(c,'biomeorchardwater',44.5,24.2,.25,4.2);asset(c,'biomeorchardwater',33.5,28.4,11,.25);}for(const [id,x,y,facing]of [['043',18,12,'down'],['163',29,25,'left'],['061',14,23,'right']])drawCompanion(c,{unit:{species:species(id)},px:x*16+8,py:y*16+8,facing,stride:0,reactionUntil:0,step:null},time,reduced);if(state.fates?.['LDR-04']==='EXECUTED'){c.save();for(let i=0;i<13;i++){c.fillStyle=['#f5e6c8','#c8abdf','#d3a3bd'][i%3];c.fillRect(41*16+i%5*5,18*16+Math.floor(i/5)*5,3,3);}c.restore();}}

